from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Low-volatility stocks tend to provide more stable returns over time. By tilting "
        "our portfolio towards these stocks, we aim to reduce overall portfolio volatility "
        "and potentially enhance risk-adjusted returns."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        symbol_volatility: dict[str, float] = {}
        for symbol in view.symbols:
            if symbol not in history["symbol"]:
                continue
            adj_closes = [float(v) for v in history.filter(pl.col("symbol") == symbol)[
                "adj_close"].drop_nulls().to_list()]
            if len(adj_closes) < self._window:
                continue
            volatility = pl.Series(adj_closes).rolling_std(window=self._window, min_periods=1).last().item()
            symbol_volatility[symbol] = volatility

        sorted_symbols = [symbol for symbol, _ in sorted(symbol_volatility.items(), key=lambda item: item[1])]
        top_symbols = sorted_symbols[:5]
        if not top_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(top_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in top_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
